import { useAuth } from "@/_core/hooks/useAuth";
import DashboardLayout from "@/components/DashboardLayout";
import { Badge } from "@/components/ui/badge";
import { Button } from "@/components/ui/button";
import { Dialog, DialogContent, DialogDescription, DialogFooter, DialogHeader, DialogTitle } from "@/components/ui/dialog";
import { Input } from "@/components/ui/input";
import { Textarea } from "@/components/ui/textarea";
import { startLogin } from "@/const";
import { downloadAdminOrdersCsv } from "@/lib/adminOrdersCsv";
import { downloadMaintenanceHistoryCsv } from "@/lib/maintenanceHistoryCsv";
import { trpc } from "@/lib/trpc";
import { Activity, ArrowRight, Boxes, CalendarClock, CheckCircle2, CircleAlert, ClipboardList, CreditCard, Download, Eye, History, KeyRound, Loader2, LockKeyhole, Package, Plus, ReceiptText, RefreshCw, Search, ServerCog, ShieldCheck, Sparkles, Store, Ticket, Users } from "lucide-react";
import { FormEvent, useEffect, useMemo, useState } from "react";
import { Link } from "wouter";
import { toast } from "sonner";

const money = new Intl.NumberFormat("pt-BR", { style: "currency", currency: "BRL" });

type CreateDialog = "category" | "product" | "server" | "coupon" | null;
type MetricTone = "emerald" | "amber" | "rose" | "sky";

const tones: Record<MetricTone, string> = {
  emerald: "border-emerald-300/15 bg-emerald-300/[.07] text-emerald-100",
  amber: "border-amber-300/15 bg-amber-300/[.07] text-amber-100",
  rose: "border-rose-300/15 bg-rose-300/[.07] text-rose-100",
  sky: "border-sky-300/15 bg-sky-300/[.07] text-sky-100",
};

function couponExpiryLabel(value: Date | string | null | undefined) {
  if (!value) return "Sem expiração";
  const expiresAt = new Date(value);
  if (Number.isNaN(expiresAt.getTime())) return "Sem expiração";
  const formatted = expiresAt.toLocaleString("pt-BR", { dateStyle: "short", timeStyle: "short" });
  if (expiresAt.getTime() <= Date.now()) return `Expirado em ${formatted}`;
  const days = Math.ceil((expiresAt.getTime() - Date.now()) / 86_400_000);
  return days > 1 ? `Expira em ${formatted} · ${days} dias` : `Expira em ${formatted}`;
}

function MetricCard({ label, value, detail, icon: Icon, tone = "emerald" }: { label: string; value: string; detail: string; icon: typeof Activity; tone?: MetricTone }) {
  return <article className="admin-metric-card"><div><p>{label}</p><strong>{value}</strong><small>{detail}</small></div><span className={`grid h-10 w-10 place-items-center rounded-xl border ${tones[tone]}`}><Icon size={18} /></span></article>;
}

function StatusBadge({ status }: { status: string }) {
  const tone = status === "FAILED" ? "bg-rose-300/10 text-rose-100" : status === "COMPLETED" || status === "PAID" || status === "ATIVO" ? "bg-emerald-300/10 text-emerald-100" : status === "WAITING_PAYMENT" || status === "PENDING" || status === "RETRYING" ? "bg-amber-300/10 text-amber-100" : "bg-white/[.07] text-slate-200";
  return <Badge className={`border-0 text-[10px] font-bold tracking-wide ${tone}`}>{status.replaceAll("_", " ")}</Badge>;
}

function SectionHeading({ eyebrow, title, description, action }: { eyebrow: string; title: string; description?: string; action?: React.ReactNode }) {
  return <div className="admin-section-heading"><div><p className="section-kicker">{eyebrow}</p><h2>{title}</h2>{description ? <p>{description}</p> : null}</div>{action}</div>;
}

function AdminContent() {
  const { user, loading } = useAuth();
  const isAdmin = user?.role === "admin";
  const utils = trpc.useUtils();
  const overview = trpc.admin.overview.useQuery(undefined, { enabled: isAdmin });
  const monthlySales = trpc.admin.monthlySales.useQuery(undefined, { enabled: isAdmin });
  const exportOrders = trpc.admin.exportOrders.useQuery(undefined, { enabled: false, retry: false });
  const exportMaintenanceHistory = trpc.admin.exportMaintenanceHistory.useQuery(undefined, { enabled: false, retry: false });
  const categories = trpc.admin.categories.useQuery(undefined, { enabled: isAdmin });
  const products = trpc.admin.products.useQuery(undefined, { enabled: isAdmin });
  const orders = trpc.admin.orders.useQuery(undefined, { enabled: isAdmin });
  const deliveries = trpc.admin.deliveries.useQuery(undefined, { enabled: isAdmin });
  const servers = trpc.admin.servers.useQuery(undefined, { enabled: isAdmin });
  const coupons = trpc.admin.coupons.useQuery(undefined, { enabled: isAdmin });
  const users = trpc.admin.users.useQuery(undefined, { enabled: isAdmin });
  const storeAvailability = trpc.admin.storeAvailability.useQuery(undefined, { enabled: isAdmin });
  const maintenanceControl = trpc.admin.maintenanceControl.useQuery(undefined, { enabled: isAdmin });

  const [dialog, setDialog] = useState<CreateDialog>(null);
  const [categoryName, setCategoryName] = useState("");
  const [categorySlug, setCategorySlug] = useState("");
  const [serverName, setServerName] = useState("");
  const [serverSlug, setServerSlug] = useState("");
  const [serverKind, setServerKind] = useState<"SURVIVAL" | "SKYBLOCK" | "BEDWARS" | "GLOBAL">("SURVIVAL");
  const [generatedKey, setGeneratedKey] = useState<string | null>(null);
  const [productName, setProductName] = useState("");
  const [productSlug, setProductSlug] = useState("");
  const [productPrice, setProductPrice] = useState("");
  const [productCategory, setProductCategory] = useState("");
  const [productServer, setProductServer] = useState("");
  const [productKind, setProductKind] = useState<"VIP" | "COINS" | "KIT" | "COSMETIC">("VIP");
  const [productDuration, setProductDuration] = useState("");
  const [productGroup, setProductGroup] = useState("");
  const [productCommands, setProductCommands] = useState("");
  const [productFeatured, setProductFeatured] = useState(false);
  const [couponCode, setCouponCode] = useState("");
  const [couponType, setCouponType] = useState<"PERCENTAGE" | "FIXED">("PERCENTAGE");
  const [couponValue, setCouponValue] = useState("");
  const [couponStartsAt, setCouponStartsAt] = useState("");
  const [couponEndsAt, setCouponEndsAt] = useState("");
  const [couponMaxUses, setCouponMaxUses] = useState("");
  const [offlineMessage, setOfflineMessage] = useState("");
  const [maintenanceMode, setMaintenanceMode] = useState<"CLOSED" | "CATALOG_ONLY">("CLOSED");
  const [maintenanceReason, setMaintenanceReason] = useState("");
  const [scheduleStart, setScheduleStart] = useState("");
  const [scheduleEnd, setScheduleEnd] = useState("");
  const [maintenanceDiscordChannelId, setMaintenanceDiscordChannelId] = useState("");
  const [maintenanceDiscordTemplate, setMaintenanceDiscordTemplate] = useState<"STANDARD" | "CONCISE" | "COMMUNITY">("STANDARD");
  const [maintenancePreviewOpen, setMaintenancePreviewOpen] = useState(false);
  const [metricsPeriod, setMetricsPeriod] = useState<"7d" | "30d" | "90d">("30d");
  const [globalSearchOpen, setGlobalSearchOpen] = useState(false);
  const [globalSearchQuery, setGlobalSearchQuery] = useState("");
  const metricsInput = useMemo(() => ({ period: metricsPeriod }), [metricsPeriod]);
  const globalSearchInput = useMemo(() => ({ query: globalSearchQuery.trim() }), [globalSearchQuery]);
  const metricsByPeriod = trpc.admin.metricsByPeriod.useQuery(metricsInput, { enabled: isAdmin });
  const globalSearch = trpc.admin.search.useQuery(globalSearchInput, { enabled: isAdmin && globalSearchOpen && globalSearchInput.query.length >= 2 });

  useEffect(() => {
    if (storeAvailability.data) setOfflineMessage(storeAvailability.data.offlineMessage);
  }, [storeAvailability.data]);
  useEffect(() => {
    const settings = maintenanceControl.data?.settings;
    if (!settings) return;
    setOfflineMessage(settings.offlineMessage);
    setMaintenanceMode(settings.maintenanceMode);
    setMaintenanceReason(settings.maintenanceReason ?? "");
    setScheduleStart(settings.scheduledStartAt ? new Date(settings.scheduledStartAt).toISOString().slice(0, 16) : "");
    setScheduleEnd(settings.scheduledEndAt ? new Date(settings.scheduledEndAt).toISOString().slice(0, 16) : "");
    setMaintenanceDiscordChannelId(settings.maintenanceDiscordChannelId ?? "");
    setMaintenanceDiscordTemplate(settings.maintenanceDiscordTemplate ?? "STANDARD");
  }, [maintenanceControl.data]);

  const invalidateStore = () => {
    utils.admin.overview.invalidate();
    utils.admin.categories.invalidate();
    utils.admin.products.invalidate();
    utils.admin.orders.invalidate();
    utils.admin.deliveries.invalidate();
    utils.admin.servers.invalidate();
    utils.admin.coupons.invalidate();
    utils.admin.users.invalidate();
    utils.admin.storeAvailability.invalidate();
    utils.admin.maintenanceControl.invalidate();
    utils.store.availability.invalidate();
    utils.catalog.categories.invalidate();
    utils.catalog.products.invalidate();
  };
  const reportMutationError = (error: { message: string }) => toast.error(error.message || "Não foi possível concluir a ação. Tente novamente.");
  const createCategory = trpc.admin.createCategory.useMutation({ onSuccess: () => { toast.success("Categoria criada."); setCategoryName(""); setCategorySlug(""); setDialog(null); invalidateStore(); }, onError: reportMutationError });
  const createServer = trpc.admin.createServer.useMutation({ onSuccess: result => { setGeneratedKey(result.apiKey); toast.success("Servidor criado. Copie a chave agora."); invalidateStore(); }, onError: reportMutationError });
  const createProduct = trpc.admin.createProduct.useMutation({ onSuccess: () => { toast.success("Produto criado."); setProductName(""); setProductSlug(""); setProductPrice(""); setProductCommands(""); setDialog(null); invalidateStore(); }, onError: reportMutationError });
  const createCoupon = trpc.admin.createCoupon.useMutation({ onSuccess: () => { toast.success("Cupom criado."); setCouponCode(""); setCouponValue(""); setCouponStartsAt(""); setCouponEndsAt(""); setCouponMaxUses(""); setDialog(null); invalidateStore(); }, onError: reportMutationError });
  const deleteCoupon = trpc.admin.deleteCoupon.useMutation({ onSuccess: result => { toast.success(result.deleted ? "Cupom excluído." : "Cupom desativado; o histórico de uso foi preservado."); invalidateStore(); }, onError: reportMutationError });
  const setStoreAvailability = trpc.admin.setStoreAvailability.useMutation({ onSuccess: result => { toast.success(result.publicOnline ? "Loja pública ativada." : "Loja pública colocada em manutenção."); setOfflineMessage(result.offlineMessage); invalidateStore(); }, onError: reportMutationError });
  const setManualMaintenance = trpc.admin.setManualMaintenance.useMutation({ onSuccess: result => { toast.success(result.publicOnline ? "Loja reaberta e aviso encaminhado ao Discord." : "Modo de manutenção atualizado e aviso encaminhado ao Discord."); invalidateStore(); }, onError: reportMutationError });
  const scheduleMaintenance = trpc.admin.scheduleMaintenance.useMutation({ onSuccess: () => { toast.success("Manutenção agendada. A loja mudará de estado automaticamente."); invalidateStore(); }, onError: reportMutationError });
  const cancelMaintenance = trpc.admin.cancelMaintenanceSchedule.useMutation({ onSuccess: () => { toast.success("Agendamento de manutenção cancelado."); invalidateStore(); }, onError: reportMutationError });
  const setMaintenanceDiscordChannel = trpc.admin.setMaintenanceDiscordChannel.useMutation({ onSuccess: () => { toast.success("Canal de avisos de manutenção atualizado."); invalidateStore(); }, onError: reportMutationError });
  const sendMaintenanceNotificationTest = trpc.admin.sendMaintenanceNotificationTest.useMutation({ onSuccess: result => { toast.success(result.channelConfigured ? "Teste de aviso enviado à fila do canal configurado." : "Teste enviado à fila do canal operacional padrão."); }, onError: reportMutationError });
  const productStatus = trpc.admin.setProductStatus.useMutation({ onSuccess: () => { toast.success("Disponibilidade atualizada."); invalidateStore(); }, onError: reportMutationError });
  const roleChange = trpc.admin.setUserRole.useMutation({ onSuccess: () => { toast.success("Acesso atualizado."); invalidateStore(); }, onError: reportMutationError });
  const retryDelivery = trpc.admin.retryDelivery.useMutation({ onSuccess: () => { toast.success("Entrega recolocada na fila."); utils.admin.deliveries.invalidate(); utils.admin.overview.invalidate(); }, onError: reportMutationError });

  const attention = useMemo(() => ({
    failed: overview.data?.failedDeliveries ?? 0,
    pending: overview.data?.pendingDeliveries ?? 0,
    orders: overview.data?.pendingOrders ?? 0,
  }), [overview.data]);
  const totalAttention = attention.failed + attention.pending + attention.orders;
  const activeProducts = products.data?.filter(item => item.active).length ?? 0;
  const failedDeliveries = useMemo(() => deliveries.data?.filter(item => item.status === "FAILED") ?? [], [deliveries.data]);
  const metricsPeriodLabel = metricsPeriod === "7d" ? "7 dias" : metricsPeriod === "30d" ? "30 dias" : "90 dias";
  const globalResultsCount = (globalSearch.data?.orders?.length ?? 0) + (globalSearch.data?.players?.length ?? 0) + (globalSearch.data?.coupons?.length ?? 0) + (globalSearch.data?.products?.length ?? 0) + (globalSearch.data?.deliveries?.length ?? 0) + (globalSearch.data?.logs?.length ?? 0);
  const monthlyMaximum = useMemo(() => Math.max(1, ...(monthlySales.data?.map(item => item.salesCents) ?? [0])), [monthlySales.data]);
  const exportOrdersCsv = async () => {
    const result = await exportOrders.refetch();
    if (result.error) return toast.error("Não foi possível gerar o arquivo de pedidos.");
    downloadAdminOrdersCsv(result.data ?? []);
    toast.success(`${result.data?.length ?? 0} pedido(s) exportado(s) em CSV.`);
  };
  const exportMaintenanceCsv = async () => {
    const result = await exportMaintenanceHistory.refetch();
    if (result.error) return toast.error("Não foi possível exportar o histórico de manutenção.");
    downloadMaintenanceHistoryCsv(result.data ?? []);
    toast.success(`${result.data?.length ?? 0} evento(s) exportado(s) em CSV.`);
  };
  const refreshDashboard = async () => {
    await Promise.all([overview.refetch(), monthlySales.refetch(), metricsByPeriod.refetch(), products.refetch(), orders.refetch(), deliveries.refetch(), coupons.refetch(), users.refetch(), storeAvailability.refetch(), maintenanceControl.refetch()]);
    toast.success("Dados do painel atualizados.");
  };
  const updateStoreAvailability = (publicOnline: boolean) => {
    if (!publicOnline && !window.confirm("Colocar a loja offline? Compras e pagamentos serão pausados, mas o painel administrativo continuará acessível.")) return;
    setStoreAvailability.mutate({ publicOnline, offlineMessage: offlineMessage.trim() || undefined });
  };
  const useMaintenanceTemplate = (template: "brief" | "scheduled" | "incident") => {
    const templates = {
      brief: { message: "Estamos realizando uma manutenção rápida. Seus pedidos já confirmados continuam protegidos e serão processados normalmente. Volte em alguns minutos.", reason: "Manutenção rápida" },
      scheduled: { message: "Estamos realizando uma manutenção programada para melhorar a loja. Seus pedidos já confirmados continuam protegidos e serão processados normalmente.", reason: "Atualização programada" },
      incident: { message: "Identificamos uma instabilidade temporária e pausamos novas compras para proteger sua experiência. Seus pedidos já confirmados continuam seguros.", reason: "Estabilidade técnica" },
    } as const;
    setOfflineMessage(templates[template].message);
    setMaintenanceReason(templates[template].reason);
  };
  const applyManualMaintenance = (publicOnline: boolean) => {
    if (!publicOnline && !window.confirm("Aplicar este modo de manutenção agora? Novas compras e pagamentos serão pausados.")) return;
    setManualMaintenance.mutate({ publicOnline, mode: maintenanceMode, offlineMessage: offlineMessage.trim(), reason: maintenanceReason.trim() || undefined });
  };
  const submitMaintenanceSchedule = (event: FormEvent) => {
    event.preventDefault();
    const startAt = new Date(scheduleStart);
    const endAt = new Date(scheduleEnd);
    if (Number.isNaN(startAt.getTime()) || Number.isNaN(endAt.getTime())) return toast.error("Informe o início e o término da manutenção.");
    scheduleMaintenance.mutate({ startAt, endAt, mode: maintenanceMode, offlineMessage: offlineMessage.trim(), reason: maintenanceReason.trim() || undefined });
  };

  if (loading) return <div className="grid min-h-80 place-items-center"><Loader2 className="animate-spin text-emerald-300" /></div>;
  if (!user) return <div className="grid min-h-screen place-items-center bg-[#07111d] p-6 text-center text-white"><div><ShieldCheck className="mx-auto text-emerald-300" size={32} /><h1 className="mt-4 text-2xl font-bold">Acesso administrativo</h1><p className="mt-2 text-sm text-slate-400">Entre com uma conta autorizada para continuar.</p><Button onClick={startLogin} className="mt-6 bg-emerald-300 text-slate-950 hover:bg-emerald-200">Entrar</Button></div></div>;
  if (!isAdmin) return <div className="grid min-h-screen place-items-center bg-[#07111d] p-6 text-center text-white"><div><ShieldCheck className="mx-auto text-rose-300" size={32} /><h1 className="mt-4 text-2xl font-bold">Acesso não autorizado</h1><p className="mt-2 max-w-md text-sm text-slate-400">Esta conta não possui permissões administrativas.</p><Link href="/" className="mt-6 inline-flex text-sm font-bold text-emerald-300">Voltar à loja</Link></div></div>;

  return <div className="min-h-full text-slate-100"><div className="mx-auto max-w-7xl space-y-5">
    <header className="admin-page-header"><div><p className="section-kicker">CENTRAL DE OPERAÇÕES</p><h1>Controle simples, decisões rápidas.</h1><p>Veja o que precisa de atenção, acompanhe resultados e acesse cada área sem navegar por painéis repetidos.</p></div><div className="admin-page-header__actions"><Button type="button" variant="outline" onClick={() => setGlobalSearchOpen(true)} className="border-white/10 bg-white/[.03] text-slate-100 hover:bg-white/[.08]"><Search size={16} /> Buscar</Button><Button type="button" variant="outline" onClick={refreshDashboard} className="border-white/10 bg-white/[.03] text-slate-100 hover:bg-white/[.08]"><RefreshCw size={16} /> Atualizar dados</Button><Button type="button" onClick={() => setDialog("product")} className="bg-emerald-300 text-slate-950 hover:bg-emerald-200"><Plus size={16} /> Novo produto</Button></div></header>

    <section className={`admin-store-status ${storeAvailability.data?.publicOnline === false ? "admin-store-status--offline" : ""}`}><div className="flex min-w-0 items-start gap-3"><span className={`admin-store-status__icon ${storeAvailability.data?.publicOnline === false ? "text-amber-200" : "text-emerald-200"}`}>{storeAvailability.data?.publicOnline === false ? <CircleAlert size={19} /> : <CheckCircle2 size={19} />}</span><div><p className="font-semibold text-white">{storeAvailability.data?.publicOnline === false ? "Loja pública em manutenção" : "Loja pública online"}</p><p>{storeAvailability.data?.publicOnline === false ? offlineMessage || "As novas compras estão pausadas até a reativação." : "Compras e pagamentos estão habilitados para os jogadores."}</p></div></div><div className="flex flex-wrap items-center gap-2"><Button type="button" disabled={setStoreAvailability.isPending || storeAvailability.isLoading} onClick={() => updateStoreAvailability(true)} size="sm" className="bg-emerald-300 text-slate-950 hover:bg-emerald-200">Deixar online</Button><Button type="button" disabled={setStoreAvailability.isPending || storeAvailability.isLoading} onClick={() => updateStoreAvailability(false)} size="sm" variant="outline" className="border-amber-300/30 text-amber-100 hover:bg-amber-300/10">Deixar offline</Button></div><details className="admin-store-status__details"><summary>Editar mensagem de manutenção</summary><Textarea value={offlineMessage} onChange={event => setOfflineMessage(event.target.value)} maxLength={280} placeholder="Mensagem exibida enquanto a loja estiver offline" className="mt-3 min-h-20" /></details></section>

    <section className="surface-panel rounded-[1.4rem] p-5 sm:p-6"><SectionHeading eyebrow="CENTRO DE MANUTENÇÃO" title="Planeje, comunique e preserve pedidos" description="Os avisos seguem automaticamente para o canal operacional do Discord; o bot continua usando somente as permissões já concedidas." action={<Button type="button" variant="outline" onClick={() => setMaintenancePreviewOpen(true)} className="border-white/10 bg-white/[.03] text-slate-100 hover:bg-white/[.08]"><Eye size={16} /> Prévia pública</Button>} />{maintenanceControl.isLoading ? <div className="grid min-h-32 place-items-center"><Loader2 className="animate-spin text-emerald-300" /></div> : <div className="maintenance-center"><div className="maintenance-protection"><LockKeyhole size={18} /><div><strong>{maintenanceControl.data?.protectedOrders ?? 0} pedido(s) protegido(s)</strong><span>Pedidos pagos, em processamento ou concluídos não são cancelados durante a manutenção.</span></div></div><div className="maintenance-templates"><span>Modelos rápidos</span><Button type="button" size="sm" variant="outline" onClick={() => useMaintenanceTemplate("brief")}>Breve</Button><Button type="button" size="sm" variant="outline" onClick={() => useMaintenanceTemplate("scheduled")}>Programada</Button><Button type="button" size="sm" variant="outline" onClick={() => useMaintenanceTemplate("incident")}>Incidente</Button></div><div className="maintenance-fields"><label><span>Modo público</span><select value={maintenanceMode} onChange={event => setMaintenanceMode(event.target.value as "CLOSED" | "CATALOG_ONLY")}><option value="CLOSED">Loja fechada</option><option value="CATALOG_ONLY">Somente catálogo</option></select><small>{maintenanceMode === "CATALOG_ONLY" ? "Produtos continuam visíveis; compras e pagamentos ficam bloqueados." : "A página pública exibe o aviso de manutenção."}</small></label><label><span>Motivo interno</span><Input value={maintenanceReason} maxLength={280} onChange={event => setMaintenanceReason(event.target.value)} placeholder="Ex.: atualização programada" /></label><label className="maintenance-fields__message"><span>Mensagem para jogadores</span><Textarea value={offlineMessage} maxLength={280} onChange={event => setOfflineMessage(event.target.value)} placeholder="Explique de forma breve o que está acontecendo." /></label></div><div className="maintenance-actions"><Button type="button" disabled={setManualMaintenance.isPending} onClick={() => applyManualMaintenance(false)} className="bg-amber-300 text-slate-950 hover:bg-amber-200">Aplicar manutenção agora</Button><Button type="button" disabled={setManualMaintenance.isPending} onClick={() => applyManualMaintenance(true)} variant="outline" className="border-emerald-300/30 text-emerald-100 hover:bg-emerald-300/10">Reabrir loja agora</Button></div><form onSubmit={submitMaintenanceSchedule} className="maintenance-schedule"><div><CalendarClock size={18} /><div><strong>Agendamento automático</strong><span>O sistema aplica e encerra a manutenção no horário escolhido, sem depender de o painel estar aberto.</span></div></div><label><span>Início</span><Input type="datetime-local" value={scheduleStart} onChange={event => setScheduleStart(event.target.value)} /></label><label><span>Término</span><Input type="datetime-local" value={scheduleEnd} onChange={event => setScheduleEnd(event.target.value)} /></label><Button type="submit" disabled={scheduleMaintenance.isPending} className="bg-sky-200 text-slate-950 hover:bg-sky-100">{scheduleMaintenance.isPending ? <Loader2 className="animate-spin" /> : "Agendar"}</Button>{maintenanceControl.data?.settings.scheduleStatus === "SCHEDULED" || maintenanceControl.data?.settings.scheduleStatus === "ACTIVE" ? <Button type="button" variant="outline" disabled={cancelMaintenance.isPending} onClick={() => { if (window.confirm("Cancelar o agendamento atual?")) cancelMaintenance.mutate(); }} className="border-rose-300/30 text-rose-100 hover:bg-rose-300/10">Cancelar agenda</Button> : null}</form><div className="maintenance-history"><div><History size={17} /><strong>Histórico recente</strong></div>{maintenanceControl.data?.history.length ? <div className="space-y-2">{maintenanceControl.data.history.map(event => <div key={event.id}><span>{event.eventType === "SCHEDULED" ? "Agendada" : event.eventType === "STARTED" ? "Iniciada" : event.eventType === "ENDED" ? "Encerrada" : event.eventType === "CANCELLED" ? "Cancelada" : "Atualizada"}</span><p>{event.reason || event.message}</p><small>{new Date(event.createdAt).toLocaleString("pt-BR", { dateStyle: "short", timeStyle: "short" })} · {event.actorType === "scheduler" ? "automático" : "administrador"}</small></div>)}</div> : <p className="text-sm text-slate-500">Nenhum evento de manutenção registrado ainda.</p>}</div></div>}</section>

    <section className="surface-panel rounded-[1.4rem] p-5 sm:p-6">
      <SectionHeading eyebrow="COMUNICAÇÃO E REGISTROS" title="Avisos e retorno previsto" description="Defina o canal e o estilo dos avisos de manutenção, valide o destino sem interromper a loja e exporte os registros." action={<Button type="button" variant="outline" onClick={exportMaintenanceCsv} disabled={exportMaintenanceHistory.isFetching} className="border-white/10 bg-white/[.03] text-slate-100 hover:bg-white/[.08]"><Download size={16} /> {exportMaintenanceHistory.isFetching ? "Gerando…" : "Exportar histórico"}</Button>} />
      <div className="grid gap-4 lg:grid-cols-[1.25fr_.75fr]">
        <div className="rounded-2xl border border-white/[.08] bg-white/[.02] p-4">
          <label className="grid gap-2"><span className="text-xs font-bold uppercase tracking-wide text-slate-400">Canal de avisos no Discord</span><Input value={maintenanceDiscordChannelId} onChange={event => setMaintenanceDiscordChannelId(event.target.value.replace(/\s/g, ""))} inputMode="numeric" placeholder="ID do canal, ex.: 1492898167405150268" className="font-mono text-xs" /></label>
          <label className="mt-4 grid gap-2"><span className="text-xs font-bold uppercase tracking-wide text-slate-400">Modelo da mensagem</span><select value={maintenanceDiscordTemplate} onChange={event => setMaintenanceDiscordTemplate(event.target.value as "STANDARD" | "CONCISE" | "COMMUNITY")} className="h-10 rounded-xl border border-white/10 bg-[#0b1725] px-3 text-sm text-slate-100"><option value="STANDARD">Padrão operacional</option><option value="CONCISE">Curto e objetivo</option><option value="COMMUNITY">Comunidade acolhedora</option></select></label>
          <div className="mt-4 flex flex-wrap gap-2"><Button type="button" disabled={setMaintenanceDiscordChannel.isPending} onClick={() => setMaintenanceDiscordChannel.mutate({ channelId: maintenanceDiscordChannelId.trim() || null, template: maintenanceDiscordTemplate })} className="bg-sky-200 text-slate-950 hover:bg-sky-100">Salvar configuração</Button><Button type="button" variant="outline" disabled={sendMaintenanceNotificationTest.isPending} onClick={() => { if (window.confirm("Enviar um teste ao canal configurado? A loja permanecerá online.")) sendMaintenanceNotificationTest.mutate(); }} className="border-emerald-300/25 text-emerald-100 hover:bg-emerald-300/10">{sendMaintenanceNotificationTest.isPending ? <Loader2 className="animate-spin" /> : "Testar aviso"}</Button></div>
          <small className="mt-3 block leading-5 text-slate-500">Informe o ID de um canal de texto do servidor Discord. Sem ID configurado, os avisos usam o canal operacional padrão. O teste não altera produtos, pagamentos ou disponibilidade.</small>
        </div>
        <div className="rounded-2xl border border-emerald-300/15 bg-emerald-300/[.05] p-4"><p className="text-xs font-bold uppercase tracking-wide text-emerald-200">Previsão para jogadores</p>{maintenanceControl.data?.settings.scheduledEndAt && ["SCHEDULED", "ACTIVE"].includes(maintenanceControl.data.settings.scheduleStatus) ? <><p className="mt-2 text-lg font-bold text-white">{new Date(maintenanceControl.data.settings.scheduledEndAt).toLocaleString("pt-BR", { dateStyle: "short", timeStyle: "short" })}</p><p className="mt-2 text-xs leading-5 text-slate-400">Este horário aparece na tela de manutenção e no modo somente catálogo.</p></> : <p className="mt-2 text-sm leading-6 text-slate-400">Agende início e término para exibir uma previsão pública de retorno.</p>}</div>
      </div>
    </section>

    {failedDeliveries.length ? <section className="admin-failure-alert"><div className="flex min-w-0 items-start gap-3"><span><CircleAlert size={19} /></span><div><p className="font-semibold">{failedDeliveries.length} entrega(s) com falha</p><p>Reprocesse a entrega ou abra a fila completa para analisar o histórico do jogador e do pedido.</p></div></div><div className="admin-failure-alert__actions">{failedDeliveries.slice(0, 2).map(delivery => <Button key={delivery.id} type="button" size="sm" variant="outline" disabled={retryDelivery.isPending} onClick={() => retryDelivery.mutate({ id: delivery.id })} className="border-rose-300/25 text-rose-100 hover:bg-rose-300/10">Reprocessar {delivery.playerName}</Button>)}<Link href="/admin/operations" className="admin-section-link">Ver fila <ArrowRight size={14} /></Link></div></section> : null}

    {overview.isError ? <div className="rounded-2xl border border-rose-300/20 bg-rose-300/[.06] p-5 text-sm text-rose-100">Não foi possível atualizar as métricas. <button className="ml-2 font-bold underline" onClick={() => overview.refetch()}>Tentar novamente</button></div> : <section className="grid gap-3 sm:grid-cols-2 xl:grid-cols-4"><MetricCard label="Vendas hoje" value={money.format((overview.data?.salesTodayCents ?? 0) / 100)} detail="Pedidos pagos no dia" icon={CreditCard} /><MetricCard label="Vendas no mês" value={money.format((overview.data?.salesMonthCents ?? 0) / 100)} detail="Faturamento confirmado" icon={ReceiptText} tone="sky" /><MetricCard label="Pedidos ativos" value={String(attention.orders)} detail="Pagamento ou processamento" icon={ClipboardList} tone={attention.orders ? "amber" : "emerald"} /><MetricCard label="Entregas em tratamento" value={String(attention.pending + attention.failed)} detail={attention.failed ? `${attention.failed} com falha` : "Fila sob controle"} icon={Package} tone={attention.failed ? "rose" : attention.pending ? "amber" : "emerald"} /></section>}

    <section className="grid gap-5 xl:grid-cols-[1.1fr_.9fr]"><article className="admin-focus-card"><div className="flex items-start justify-between gap-4"><div><p className="section-kicker">PRIORIDADE AGORA</p><h2>{totalAttention ? `${totalAttention} item(ns) pedem atenção` : "A operação está em ordem"}</h2><p>{totalAttention ? "Vá direto à fila para revisar pagamentos, reprocessar entregas e resolver falhas sem procurar em listas extensas." : "Não há pedidos ou entregas pendentes para tratar neste momento."}</p></div><span className={`admin-focus-card__icon ${totalAttention ? "text-amber-200" : "text-emerald-200"}`}>{totalAttention ? <CircleAlert size={22} /> : <CheckCircle2 size={22} />}</span></div><div className="admin-focus-card__facts"><span><strong>{attention.failed}</strong> falhas</span><span><strong>{attention.pending}</strong> entregas</span><span><strong>{attention.orders}</strong> pedidos</span></div><Link href="/admin/operations" className="admin-link-button">Abrir operações <ArrowRight size={15} /></Link></article><article className="surface-panel rounded-[1.4rem] p-5"><SectionHeading eyebrow="ATALHOS" title="Gestão por área" description="Cada fluxo tem uma área própria, sem duplicar controles na tela inicial." /><div className="grid gap-2 sm:grid-cols-3 xl:grid-cols-1"><Link href="/admin/catalog" className="admin-quick-action"><Boxes size={17} /><span><strong>Catálogo</strong><small>Produtos e cupons</small></span><ArrowRight size={15} /></Link><Link href="/admin/operations" className="admin-quick-action"><ClipboardList size={17} /><span><strong>Operações</strong><small>Pedidos e entregas</small></span><ArrowRight size={15} /></Link><Link href="/admin/community" className="admin-quick-action"><Users size={17} /><span><strong>Comunidade</strong><small>Discord e conteúdo</small></span><ArrowRight size={15} /></Link></div></article></section>

    <section className="surface-panel rounded-[1.4rem] p-5 sm:p-6"><SectionHeading eyebrow="ANÁLISE COMERCIAL" title="Vendas confirmadas" description="Alterne o período para comparar faturamento, pedidos e ticket médio usando somente pagamentos confirmados." action={<Button type="button" variant="outline" onClick={exportOrdersCsv} disabled={exportOrders.isFetching} className="border-white/10 bg-white/[.03] text-slate-100 hover:bg-white/[.08]"><Download size={16} /> {exportOrders.isFetching ? "Gerando…" : "Exportar CSV"}</Button>} /><div className="admin-period-filter" aria-label="Período das métricas">{(["7d", "30d", "90d"] as const).map(period => <button type="button" key={period} onClick={() => setMetricsPeriod(period)} className={metricsPeriod === period ? "is-active" : ""}>{period === "7d" ? "7 dias" : period === "30d" ? "30 dias" : "90 dias"}</button>)}</div>{metricsByPeriod.isLoading ? <div className="grid min-h-24 place-items-center"><Loader2 className="animate-spin text-emerald-300" /></div> : <div className="admin-period-metrics"><div><span>Resumo de {metricsPeriodLabel}</span><strong>{money.format((metricsByPeriod.data?.salesCents ?? 0) / 100)}</strong><small>Faturamento confirmado</small></div><div><span>Pedidos confirmados</span><strong>{metricsByPeriod.data?.paidOrders ?? 0}</strong><small>No período selecionado</small></div><div><span>Ticket médio</span><strong>{money.format((metricsByPeriod.data?.averageOrderCents ?? 0) / 100)}</strong><small>Por pedido confirmado</small></div></div>}{monthlySales.isLoading ? <div className="grid h-48 place-items-center"><Loader2 className="animate-spin text-emerald-300" /></div> : monthlySales.isError ? <div className="rounded-2xl border border-rose-300/20 bg-rose-300/[.06] p-4 text-sm text-rose-100">Não foi possível carregar o histórico mensal. <button type="button" className="font-bold underline" onClick={() => monthlySales.refetch()}>Tentar novamente</button></div> : <div className="monthly-chart mt-5" role="img" aria-label="Gráfico de vendas mensais"><div className="monthly-chart__grid" />{monthlySales.data?.map(month => <div className="monthly-chart__column" key={month.key}><div className="monthly-chart__value">{money.format(month.salesCents / 100)}</div><div className="monthly-chart__track"><div className="monthly-chart__bar" style={{ height: `${Math.max(month.salesCents ? 10 : 2, Math.round((month.salesCents / monthlyMaximum) * 100))}%` }} title={`${month.paidOrders} pedido(s) confirmado(s)`} /></div><div className="monthly-chart__label">{month.label}</div><div className="monthly-chart__meta">{month.paidOrders} ped.</div></div>)}</div>}</section>

    <section className="grid gap-5 xl:grid-cols-2"><article className="surface-panel rounded-[1.4rem] p-5 sm:p-6"><SectionHeading eyebrow="MOVIMENTAÇÃO" title="Últimos pedidos" action={<Link href="/admin/operations" className="admin-section-link">Ver operações</Link>} /><div className="admin-list">{orders.data?.slice(0, 5).map(order => <div key={order.id}><div className="min-w-0"><strong className="font-mono">{order.orderNumber}</strong><small>{order.playerName} · {money.format(order.totalCents / 100)}</small></div><StatusBadge status={order.status} /></div>) || <div><p className="text-sm text-slate-400">Nenhum pedido encontrado.</p></div>}</div></article><article className="surface-panel rounded-[1.4rem] p-5 sm:p-6"><SectionHeading eyebrow="ENTREGAS" title="Últimas movimentações" action={<Link href="/admin/operations" className="admin-section-link">Abrir fila</Link>} /><div className="admin-list">{deliveries.data?.slice(0, 5).map(delivery => <div key={delivery.id}><div className="min-w-0"><strong>{delivery.playerName} <span className="font-normal text-slate-500">· {delivery.serverName}</span></strong><small>Tentativa {delivery.attemptCount}/{delivery.maxAttempts}{delivery.lastError ? ` · ${delivery.lastError}` : ""}</small></div><StatusBadge status={delivery.status} /></div>) || <div><p className="text-sm text-slate-400">Nenhuma entrega encontrada.</p></div>}</div></article></section>

    <section className="grid gap-5 xl:grid-cols-[1.15fr_.85fr]"><article className="surface-panel rounded-[1.4rem] p-5 sm:p-6"><SectionHeading eyebrow="CATÁLOGO" title={`${activeProducts} produto(s) à venda`} description="Mantenha os controles rápidos aqui e faça edições completas na área de catálogo." action={<div className="flex gap-2"><Button type="button" size="sm" variant="outline" onClick={() => setDialog("category")} className="border-white/10 text-slate-100"><Plus size={15} /> Categoria</Button><Link href="/admin/catalog" className="admin-section-link">Gerenciar</Link></div>} /><div className="grid gap-2 sm:grid-cols-2">{products.data?.slice(0, 6).map(product => <div key={product.id} className="admin-compact-item"><div className="min-w-0"><p>{product.name}</p><small>{product.categoryName} · {money.format(product.priceCents / 100)}</small></div><div className="flex items-center gap-2"><StatusBadge status={product.active ? "ATIVO" : "INATIVO"} /><Button type="button" onClick={() => productStatus.mutate({ id: product.id, active: !product.active })} disabled={productStatus.isPending} variant="outline" size="sm" className="h-8 border-white/10 px-2 text-xs text-slate-200">{product.active ? "Pausar venda" : "Publicar"}</Button></div></div>) || <p className="text-sm text-slate-400">Nenhum produto cadastrado.</p>}</div></article><article className="surface-panel rounded-[1.4rem] p-5 sm:p-6"><SectionHeading eyebrow="CAMPANHAS E ACESSOS" title="Administração rápida" action={<div className="flex flex-wrap gap-2"><Button type="button" size="sm" variant="outline" onClick={() => setDialog("server")} className="border-emerald-300/25 text-emerald-100"><KeyRound size={15} /> Gerar chave</Button><Button type="button" size="sm" variant="outline" onClick={() => setDialog("coupon")} className="border-white/10 text-slate-100"><Ticket size={15} /> Novo cupom</Button></div>} /><div className="space-y-2">{coupons.data?.slice(0, 3).map(coupon => <div key={coupon.id} className="admin-compact-item"><div><p className="font-mono">{coupon.code}</p><small>{coupon.type === "PERCENTAGE" ? `${(coupon.percentageBasisPoints ?? 0) / 100}%` : money.format((coupon.fixedDiscountCents ?? 0) / 100)} · {coupon.usedCount ?? 0}/{coupon.maxUses ?? "∞"} usos</small></div><Button type="button" size="sm" variant="outline" disabled={deleteCoupon.isPending} onClick={() => { if (window.confirm(`Excluir o cupom ${coupon.code}? Essa ação não pode ser desfeita.`)) deleteCoupon.mutate({ id: coupon.id }); }} className="h-8 border-rose-300/20 px-2 text-xs text-rose-200 hover:bg-rose-300/10">Excluir</Button></div>)}<div className="mt-4 border-t border-white/[.07] pt-3"><p className="mb-2 text-xs font-bold uppercase tracking-wide text-slate-500">Acessos administrativos</p>{users.data?.map(account => <div key={account.id} className="flex items-center justify-between gap-3 py-1.5"><span className="truncate text-sm text-slate-300">{account.name || account.email || `Usuário #${account.id}`}</span><Button type="button" size="sm" variant="outline" disabled={roleChange.isPending || account.id === user.id} onClick={() => roleChange.mutate({ userId: account.id, role: account.role === "admin" ? "user" : "admin" })} className="h-7 border-white/10 text-[11px] text-slate-200">{account.role === "admin" ? "Remover" : "Promover"}</Button></div>)}</div></div></article></section>

    <section className="admin-growth-strip"><Sparkles size={18} /><p><strong>Melhoria prática:</strong> use “Atualizar dados” para uma leitura manual imediata e concentre alterações de catálogo, operações e comunidade nas áreas específicas.</p><Store size={18} /></section>
  </div>

  <Dialog open={globalSearchOpen} onOpenChange={open => { setGlobalSearchOpen(open); if (!open) setGlobalSearchQuery(""); }}><DialogContent className="max-h-[90vh] max-w-2xl overflow-y-auto border-white/10 bg-[#0b1725] text-slate-100"><DialogHeader><DialogTitle>Busca global</DialogTitle><DialogDescription>Localize pedidos, jogadores, produtos, entregas, cupons e eventos sem navegar entre áreas administrativas.</DialogDescription></DialogHeader><label className="relative block"><Search className="pointer-events-none absolute left-3 top-1/2 -translate-y-1/2 text-slate-500" size={17} /><Input autoFocus value={globalSearchQuery} onChange={event => setGlobalSearchQuery(event.target.value)} placeholder="Ex.: PSC-100, nome do jogador ou BEMVINDO10" className="pl-10" /></label>{globalSearchInput.query.length < 2 ? <p className="py-5 text-center text-sm text-slate-400">Digite ao menos 2 caracteres para pesquisar.</p> : globalSearch.isLoading ? <div className="grid min-h-28 place-items-center"><Loader2 className="animate-spin text-emerald-300" /></div> : globalSearch.isError ? <p className="py-5 text-center text-sm text-rose-200">Não foi possível concluir a busca. Tente novamente.</p> : <div className="mt-2 space-y-4">{globalResultsCount ? <p className="text-xs font-bold uppercase tracking-wide text-slate-500">{globalResultsCount} resultado(s)</p> : <p className="py-5 text-center text-sm text-slate-400">Nenhum registro encontrado.</p>}{globalSearch.data?.orders?.length ? <div><p className="mb-2 text-xs font-bold uppercase tracking-wide text-emerald-200">Pedidos</p><div className="space-y-2">{globalSearch.data.orders.map(order => <Link key={order.id} href="/admin/operations" onClick={() => setGlobalSearchOpen(false)} className="admin-search-result"><span><strong className="font-mono">{order.orderNumber}</strong><small>{order.playerName} · {money.format(order.totalCents / 100)}</small></span><StatusBadge status={order.status} /></Link>)}</div></div> : null}{globalSearch.data?.players?.length ? <div><p className="mb-2 text-xs font-bold uppercase tracking-wide text-sky-200">Jogadores</p><div className="space-y-2">{globalSearch.data.players.map(player => <Link key={player.id} href={`/admin/players/${player.id}`} onClick={() => setGlobalSearchOpen(false)} className="admin-search-result"><span><strong>{player.username}</strong><small>{player.uuid}</small></span><Users size={16} className="text-sky-200" /></Link>)}</div></div> : null}{globalSearch.data?.deliveries?.length ? <div><p className="mb-2 text-xs font-bold uppercase tracking-wide text-rose-200">Entregas</p><div className="space-y-2">{globalSearch.data.deliveries.map(delivery => <Link key={delivery.id} href={`/admin/deliveries/${delivery.id}`} onClick={() => setGlobalSearchOpen(false)} className="admin-search-result"><span><strong className="font-mono">{delivery.orderNumber}</strong><small>{delivery.playerName} · {delivery.serverName}</small></span><StatusBadge status={delivery.status} /></Link>)}</div></div> : null}{globalSearch.data?.products?.length ? <div><p className="mb-2 text-xs font-bold uppercase tracking-wide text-violet-200">Produtos</p><div className="space-y-2">{globalSearch.data.products.map(product => <Link key={product.id} href="/admin/catalog" onClick={() => setGlobalSearchOpen(false)} className="admin-search-result"><span><strong>{product.name}</strong><small>/{product.slug} · {money.format(product.priceCents / 100)}</small></span><StatusBadge status={product.active ? "ATIVO" : "INATIVO"} /></Link>)}</div></div> : null}{globalSearch.data?.coupons?.length ? <div><p className="mb-2 text-xs font-bold uppercase tracking-wide text-amber-200">Cupons</p><div className="space-y-2">{globalSearch.data.coupons.map(coupon => <Link key={coupon.id} href="/admin/catalog" onClick={() => setGlobalSearchOpen(false)} className="admin-search-result"><span><strong className="font-mono">{coupon.code}</strong><small>{coupon.description || "Sem descrição"}</small></span><StatusBadge status={coupon.active ? "ATIVO" : "INATIVO"} /></Link>)}</div></div> : null}{globalSearch.data?.logs?.length ? <div><p className="mb-2 text-xs font-bold uppercase tracking-wide text-slate-300">Auditoria</p><div className="space-y-2">{globalSearch.data.logs.map(log => <Link key={log.id} href="/admin/operations" onClick={() => setGlobalSearchOpen(false)} className="admin-search-result"><span><strong className="font-mono">{log.action}</strong><small>{log.entityType}{log.entityId ? ` · ${log.entityId}` : ""}</small></span><History size={16} className="text-slate-300" /></Link>)}</div></div> : null}</div>}</DialogContent></Dialog>

  <Dialog open={maintenancePreviewOpen} onOpenChange={setMaintenancePreviewOpen}><DialogContent className="border-white/10 bg-[#0b1725] text-slate-100"><DialogHeader><DialogTitle>Prévia para jogadores</DialogTitle><DialogDescription>Esta é a mensagem que será exibida no modo fechado ou comunicada no modo somente catálogo.</DialogDescription></DialogHeader><div className="rounded-[1.2rem] border border-amber-300/20 bg-[#07111d] p-6 text-center"><div className="mx-auto grid h-12 w-12 place-items-center rounded-2xl border border-amber-300/25 bg-amber-300/[.08] text-amber-200"><ShieldCheck size={22} /></div><p className="section-kicker mt-5">{maintenanceMode === "CATALOG_ONLY" ? "CATÁLOGO DISPONÍVEL" : "MANUTENÇÃO PROGRAMADA"}</p><h3 className="mt-3 text-xl font-bold text-white">{maintenanceMode === "CATALOG_ONLY" ? "Você pode consultar os benefícios" : "A loja está temporariamente offline"}</h3><p className="mt-4 text-sm leading-7 text-slate-300">{offlineMessage || "Informe uma mensagem para a manutenção."}</p><p className="mt-5 text-xs leading-5 text-slate-500">{maintenanceMode === "CATALOG_ONLY" ? "Compras e pagamentos estarão pausados até o fim da manutenção." : "Compras e pagamentos estarão pausados enquanto a manutenção estiver ativa."}</p></div><DialogFooter><Button type="button" onClick={() => setMaintenancePreviewOpen(false)} className="bg-emerald-300 text-slate-950 hover:bg-emerald-200">Fechar prévia</Button></DialogFooter></DialogContent></Dialog>

  <Dialog open={dialog === "category"} onOpenChange={open => !open && setDialog(null)}><DialogContent className="border-white/10 bg-[#0b1725] text-slate-100"><DialogHeader><DialogTitle>Nova categoria</DialogTitle><DialogDescription>Crie uma seção para organizar os benefícios na vitrine.</DialogDescription></DialogHeader><form onSubmit={(event: FormEvent) => { event.preventDefault(); createCategory.mutate({ name: categoryName.trim(), slug: categorySlug.trim().toLowerCase() }); }} className="space-y-3"><Input required value={categoryName} onChange={event => setCategoryName(event.target.value)} placeholder="Ex.: VIPs" /><Input required value={categorySlug} onChange={event => setCategorySlug(event.target.value.toLowerCase())} placeholder="vips" className="font-mono" /><DialogFooter><Button type="submit" disabled={createCategory.isPending} className="bg-emerald-300 text-slate-950 hover:bg-emerald-200">{createCategory.isPending ? "Criando…" : "Criar categoria"}</Button></DialogFooter></form></DialogContent></Dialog>

  <Dialog open={dialog === "product"} onOpenChange={open => !open && setDialog(null)}><DialogContent className="max-h-[90vh] max-w-3xl overflow-y-auto border-white/10 bg-[#0b1725] text-slate-100"><DialogHeader><DialogTitle>Novo produto</DialogTitle><DialogDescription>Defina preço, destino e comando de entrega antes de publicar.</DialogDescription></DialogHeader><form onSubmit={(event: FormEvent) => { event.preventDefault(); const priceCents = Math.round(Number(productPrice.replace(",", ".")) * 100); const deliveryCommands = productCommands.split("\n").map(command => command.trim()).filter(Boolean); if (!Number.isInteger(priceCents) || priceCents < 1) return toast.error("Informe um preço válido maior que zero."); if (!productCategory || !productServer) return toast.error("Selecione categoria e servidor de destino."); if (!deliveryCommands.length && !(productKind === "VIP" && productGroup.trim())) return toast.error("Informe um comando ou um grupo LuckPerms para o VIP."); createProduct.mutate({ categoryId: Number(productCategory), name: productName.trim(), slug: productSlug.trim().toLowerCase(), kind: productKind, priceCents, durationDays: productDuration ? Number(productDuration) : null, luckPermsGroup: productGroup.trim() || undefined, deliveryCommands, featured: productFeatured, position: 0, serverIds: [Number(productServer)] }); }} className="grid gap-3 sm:grid-cols-2"><Input required value={productName} onChange={event => setProductName(event.target.value)} placeholder="Nome do produto" /><Input required value={productSlug} onChange={event => setProductSlug(event.target.value.toLowerCase())} placeholder="slug-do-produto" className="font-mono" /><select value={productKind} onChange={event => setProductKind(event.target.value as typeof productKind)} className="admin-select"><option value="VIP">VIP</option><option value="COINS">Coins</option><option value="KIT">Kit</option><option value="COSMETIC">Cosmético</option></select><Input required value={productPrice} onChange={event => setProductPrice(event.target.value)} inputMode="decimal" placeholder="Preço em R$" /><select required value={productCategory} onChange={event => setProductCategory(event.target.value)} className="admin-select"><option value="">Categoria</option>{categories.data?.filter(category => category.active).map(category => <option key={category.id} value={category.id}>{category.name}</option>)}</select><select required value={productServer} onChange={event => setProductServer(event.target.value)} className="admin-select"><option value="">Servidor de destino</option>{servers.data?.filter(server => server.active).map(server => <option key={server.id} value={server.id}>{server.name}</option>)}</select><select value={productDuration} onChange={event => setProductDuration(event.target.value)} className="admin-select"><option value="">Permanente</option><option value="7">7 dias</option><option value="15">15 dias</option><option value="30">30 dias</option><option value="90">90 dias</option><option value="365">365 dias</option></select><Input value={productGroup} onChange={event => setProductGroup(event.target.value)} placeholder="Grupo LuckPerms (opcional)" /><Textarea value={productCommands} onChange={event => setProductCommands(event.target.value)} placeholder="Um comando por linha. Ex.: lp user {player} parent add vip" className="min-h-24 font-mono sm:col-span-2" /><label className="flex items-center gap-2 text-sm text-slate-300 sm:col-span-2"><input type="checkbox" checked={productFeatured} onChange={event => setProductFeatured(event.target.checked)} /> Destacar este produto na vitrine</label><DialogFooter className="sm:col-span-2"><Button type="submit" disabled={createProduct.isPending} className="bg-emerald-300 text-slate-950 hover:bg-emerald-200">{createProduct.isPending ? "Criando…" : "Criar produto"}</Button></DialogFooter></form></DialogContent></Dialog>

  <Dialog open={dialog === "server"} onOpenChange={open => { if (!open) { setDialog(null); setGeneratedKey(null); } }}><DialogContent className="border-white/10 bg-[#0b1725] text-slate-100"><DialogHeader><DialogTitle>Novo servidor Minecraft</DialogTitle><DialogDescription>A chave é exibida apenas uma vez e deve ser guardada no runtime do Paper.</DialogDescription></DialogHeader>{generatedKey ? <div className="rounded-xl border border-amber-300/25 bg-amber-300/[.08] p-4"><p className="text-xs font-bold text-amber-100">COPIE A CHAVE AGORA</p><code className="mt-3 block break-all rounded-lg bg-slate-950 p-3 text-xs text-white">{generatedKey}</code><Button type="button" onClick={() => navigator.clipboard?.writeText(generatedKey).then(() => toast.success("Chave copiada."))} className="mt-3 bg-amber-200 text-slate-950 hover:bg-amber-100">Copiar chave</Button></div> : <form onSubmit={(event: FormEvent) => { event.preventDefault(); createServer.mutate({ name: serverName.trim(), slug: serverSlug.trim().toLowerCase(), kind: serverKind }); }} className="grid gap-3"><Input required value={serverName} onChange={event => setServerName(event.target.value)} placeholder="Survival" /><Input required value={serverSlug} onChange={event => setServerSlug(event.target.value.toLowerCase())} placeholder="survival" className="font-mono" /><select value={serverKind} onChange={event => setServerKind(event.target.value as typeof serverKind)} className="admin-select"><option value="SURVIVAL">Survival</option><option value="SKYBLOCK">Skyblock</option><option value="BEDWARS">BedWars</option><option value="GLOBAL">Global</option></select><DialogFooter><Button type="submit" disabled={createServer.isPending} className="bg-emerald-300 text-slate-950 hover:bg-emerald-200"><KeyRound size={16} /> Gerar chave</Button></DialogFooter></form>}</DialogContent></Dialog>

  <Dialog open={dialog === "coupon"} onOpenChange={open => !open && setDialog(null)}><DialogContent className="border-white/10 bg-[#0b1725] text-slate-100"><DialogHeader><DialogTitle>Novo cupom</DialogTitle><DialogDescription>Crie um desconto, defina o período e limite a quantidade total de usos quando necessário.</DialogDescription></DialogHeader><form onSubmit={(event: FormEvent) => { event.preventDefault(); const code = couponCode.trim().toUpperCase(); const raw = Number(couponValue.trim().replace(",", ".")); const startsAt = couponStartsAt ? new Date(couponStartsAt) : null; const endsAt = couponEndsAt ? new Date(couponEndsAt) : null; const maxUses = couponMaxUses ? Number(couponMaxUses) : null; if (!/^[A-Z0-9_-]{3,48}$/.test(code)) return toast.error("Use entre 3 e 48 letras, números, hífen ou sublinhado."); if (!Number.isFinite(raw) || raw <= 0 || (couponType === "PERCENTAGE" && raw > 100)) return toast.error("Informe um desconto válido."); if (maxUses !== null && (!Number.isInteger(maxUses) || maxUses < 1)) return toast.error("Informe um limite total de usos válido."); if (startsAt && endsAt && endsAt <= startsAt) return toast.error("A expiração deve ocorrer depois do início do cupom."); createCoupon.mutate({ code, type: couponType, percentageBasisPoints: couponType === "PERCENTAGE" ? Math.round(raw * 100) : undefined, fixedDiscountCents: couponType === "FIXED" ? Math.round(raw * 100) : undefined, startsAt, endsAt, maxUses, maxUsesPerPlayer: 1, active: true }); }} className="grid gap-3 sm:grid-cols-2"><Input required value={couponCode} onChange={event => setCouponCode(event.target.value.toUpperCase())} placeholder="PLAY10" className="font-mono" /><select value={couponType} onChange={event => setCouponType(event.target.value as typeof couponType)} className="admin-select"><option value="PERCENTAGE">Percentual</option><option value="FIXED">Valor fixo</option></select><Input required value={couponValue} onChange={event => setCouponValue(event.target.value)} inputMode="decimal" placeholder={couponType === "PERCENTAGE" ? "10 para 10%" : "10,00"} /><label className="text-xs text-slate-300">Limite total de usos<input value={couponMaxUses} onChange={event => setCouponMaxUses(event.target.value)} type="number" min="1" step="1" placeholder="Ilimitado" className="mt-1 block h-10 w-full rounded-xl border border-white/10 bg-white/5 px-3 text-sm text-slate-100" /></label><span className="text-xs text-slate-400 sm:col-span-2">Deixe a validade e o limite total vazios para manter a campanha sem expiração e sem limite geral.</span><label className="text-xs text-slate-300">Disponível a partir de<input value={couponStartsAt} onChange={event => setCouponStartsAt(event.target.value)} type="datetime-local" className="mt-1 block h-10 w-full rounded-xl border border-white/10 bg-white/5 px-3 text-sm text-slate-100" /></label><label className="text-xs text-slate-300">Expira em<input value={couponEndsAt} onChange={event => setCouponEndsAt(event.target.value)} type="datetime-local" className="mt-1 block h-10 w-full rounded-xl border border-white/10 bg-white/5 px-3 text-sm text-slate-100" /></label><p className="rounded-xl border border-emerald-300/15 bg-emerald-300/[.06] px-3 py-2 text-xs leading-5 text-emerald-100 sm:col-span-2">{couponExpiryLabel(couponEndsAt || null)} · {couponMaxUses ? `Limite total: ${couponMaxUses} uso${couponMaxUses === "1" ? "" : "s"}` : "Uso total ilimitado"}</p><DialogFooter className="sm:col-span-2"><Button type="submit" disabled={createCoupon.isPending} className="bg-emerald-300 text-slate-950 hover:bg-emerald-200">{createCoupon.isPending ? "Criando…" : "Criar cupom"}</Button></DialogFooter></form></DialogContent></Dialog>
  </div>;
}

export default function AdminDashboard() {
  return <DashboardLayout><AdminContent /></DashboardLayout>;
}
